#include <bits/stdc++.h>
using namespace std;

using LL = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    LL n;

    while (cin >> n) {
        LL p = n + n - 1;
        LL s = 9;
        int d = 0;

        while (p >= s) {
            ++d;
            if (s > (LLONG_MAX - 9) / 10)
                break;
            s = s * 10 + 9;
        }

        vector<LL> x;

        int t = d;
        s = 0;
        while (t--) {
            s = s * 10 + 9;
        }

        x.push_back(s);

        while (s > 0 && s <= p / 10) {
            x.push_back(s);
            s *= 10;
        }

        for (int i = 1; i < 9; ++i) {
            LL value = i;
            t = d;

            while (t--) {
                value = value * 10 + 9;
            }

            if (value <= p)
                x.push_back(value);
        }

        LL sum = 0;

        for (LL value : x) {
            LL minimum = min(n, value);

            if (minimum == value)
                sum += minimum / 2;
            else
                sum += llabs(value / 2 - minimum);
        }

        cout << sum << '\n';
    }

    return 0;
}

